//! Tracked/tracked_tests over actual current raw loans and native declaration/body owners.
//! Returned rows are DATA; only the host's CODE_MAPS_DM discovery/current guard
//! and complete selected phase can authorize publication. No default context is inferred.
use crate::{tracked_policy as policy,tracked_named_arguments_native::Requests,reactive_original_source::ReadSource,captured_raw_file::{Config,RawPolicyViews},reactive_raw_policy_pages::RawPolicyPages,captured_generator_budget::Budget,captured_reactive_reads::Failure,key_policy_control::{self as kc,Control},captured_allow_annotations::Operation,lint::{Site,AllowUse}};
use std::{collections::{BTreeMap,BTreeSet},path::Path,sync::Arc,io};
fn oom(b:&Budget,message:impl Into<String>)->Failure{b.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message.into()))}
fn check(b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{b.require().map_err(|m|oom(b,m))?;poll()?;b.require().map_err(|m|oom(b,m))}
fn finish<T>(pending:Result<T,Failure>,b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<T,Failure>{if matches!(&pending,Err(Failure::Operational(_))){return pending}check(b,poll)?;pending}
struct Phase{budget:Arc<Budget>,ok:bool}impl Drop for Phase{fn drop(&mut self){if !self.ok{self.budget.keep_failed_scratch()}}}
pub struct TrackedData{tests:bool,sites:Vec<Site>,source_text:Vec<String>,allows:Vec<AllowUse>,notes:Vec<String>,digests:BTreeMap<String,[u8;20]>}
impl TrackedData{pub fn metadata(&self)->&'static crate::lint::Meta{policy::metadata(self.tests)}pub fn sites(&self)->&[Site]{&self.sites}pub fn source_text(&self)->&[String]{&self.source_text}pub fn allow_used(&self)->&[AllowUse]{&self.allows}pub fn notes(&self)->&[String]{&self.notes}pub fn allow_source_digest(&self,relative:&str)->Option<&[u8;20]>{self.digests.get(relative)}
 pub fn serialize_data<S:serde::Serializer>(&self,serializer:S)->Result<S::Ok,S::Error>{use serde::ser::SerializeTuple;let mut rows=serializer.serialize_tuple(6)?;rows.serialize_element(&self.tests)?;rows.serialize_element(&self.sites)?;rows.serialize_element(&self.source_text)?;rows.serialize_element(&self.allows)?;rows.serialize_element(&self.notes)?;rows.serialize_element(&self.digests)?;rows.end()}
 pub fn retained_charge(&self)->Option<usize>{let mut n=std::mem::size_of::<Self>().checked_add(self.sites.capacity().checked_mul(std::mem::size_of::<Site>())?)?.checked_add(self.source_text.capacity().checked_mul(std::mem::size_of::<String>())?)?.checked_add(self.allows.capacity().checked_mul(std::mem::size_of::<AllowUse>())?)?.checked_add(self.notes.capacity().checked_mul(std::mem::size_of::<String>())?)?;for s in &self.sites{for word in [&s.rule,&s.rel,&s.msg,&s.key,&s.ident]{n=n.checked_add(word.capacity())?;}}for s in self.source_text.iter().chain(&self.notes){n=n.checked_add(s.capacity())?;}for a in &self.allows{for word in [&a.rel,&a.name,&a.code]{n=n.checked_add(word.capacity())?;}}for path in self.digests.keys(){n=n.checked_add(2048)?.checked_add(path.capacity())?;}Some(n)}
}
fn selected(config:&Config,relative:&str,tests:bool)->bool{if tests{policy::TEST_PREFIXES.iter().any(|prefix|relative.starts_with(prefix))}else{!config.policy_path_exempt("tracked","",relative)}}
fn list_schema(inputs:&dm_analysis::policy_inputs::PolicyInputs,owner:&str,var:&str,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<bool,Failure>{check(root,poll)?;let temporary=Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?;let pending=(||{let tree=inputs.archive().tree();let profile=tree.checker_builtin_profile().ok_or("tracked list schema lacks actual native profile")?;let proof=tree.validated_checker_profile(profile).map_err(|error|Failure::Unsupported(format!("tracked list schema profile: {error:?}")))?;if !tree.checker_source_type_presence_validated(profile,owner,&proof).map_err(|error|Failure::Unsupported(format!("tracked list source owner: {error:?}")))?{return Ok(false)}let Some(fact)=dm_analysis::checker_variable_facts::variable_original_validated(tree,&proof,profile,dm_ir::SymbolId::of(owner),dm_ir::SymbolId::of(var))?else{return Ok(false)};let Some(formal)=fact.formal else{return Ok(fact.metadata.declared_type()==Some(dm_ir::SymbolId::of("/list")))};inputs.archive().checker_variable_qualifiers(formal,profile)?;if let Some(array)=&fact.metadata.array{if array.dimensions.is_empty(){return Err("tracked array dimensions have not been issued".into())}return Ok(true)}let width=[fact.metadata.declared_type(),fact.metadata.list_element_type(),fact.metadata.array.as_ref().and_then(|array|array.element_type)].into_iter().flatten().try_fold(0usize,|n,id|tree.symbols().text(id).and_then(|word|n.checked_add(word.len()))).ok_or_else(||oom(&temporary,"tracked actual list type spelling absent/overflow"))?;temporary.charge(width.checked_mul(64).and_then(|n|n.checked_add(4096)).ok_or_else(||oom(&temporary,"tracked list schema temporary overflow"))?).map_err(|m|oom(&temporary,m))?;let properties=inputs.archive().checker_variable_properties(formal,profile)?;Ok(properties.declared_hint().is_some_and(|hint|hint=="/list"||hint.starts_with("/list/")))})();let pending=finish(pending,&temporary,poll);if pending.is_err(){temporary.keep_failed_scratch()}drop(temporary);pending}
fn kept(f:&crate::tree::SourceFile,line:usize,temp:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<Option<(usize,String)>,Failure>{let mut work=Operation{budget:temp,poll};let raw=f.raw();if line>=1&&line<=raw.num_lines(){if let Some(code)=crate::allow::keeps_with(raw.line(line),"tracked",&mut work)?{return Ok(Some((line,code.unwrap_or_default())))}}if line>=2&&crate::util::py_lstrip(raw.line(line-1)).starts_with("//"){if let Some(code)=crate::allow::keeps_with(raw.line(line-1),"tracked",&mut work)?{return Ok(Some((line-1,code.unwrap_or_default())))}}Ok(None)}
fn allow(data:&mut TrackedData,f:&crate::tree::SourceFile,line:usize,temp:&Budget,keep:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<bool,Failure>{let Some((line,code))=kept(f,line,temp,poll)?else{return Ok(false)};if !data.allows.iter().any(|used|used.rel==f.rel&&used.line as usize==line&&used.name=="tracked"&&used.code==code){let mut work=Operation{budget:keep,poll};kc::row(&mut work,&mut data.allows)?;keep.charge(code.capacity()).map_err(|m|oom(keep,m))?;data.allows.push(AllowUse{rel:kc::own(&mut work,&f.rel)?,line:u32::try_from(line).map_err(|_|oom(keep,"tracked ALLOW line overflow"))?,name:kc::own(&mut work,"tracked")?,code});}if !data.digests.contains_key(&f.rel){let mut work=Operation{budget:keep,poll};kc::reserve(&mut work,||Some(2048))?;data.digests.insert(kc::own(&mut work,&f.rel)?,crate::captured_raw_file::source_allow_digest(f));}Ok(true)}
/// Explicit actual body demand is mandatory for compiled named-argument facts.
/// No fake empty body provider or successful callback issues complete coverage.
pub fn collect_from_pages(inputs:&dm_analysis::policy_inputs::PolicyInputs,root_path:&Path,pages:&dyn RawPolicyPages,config:&Config,tests:bool,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,body:&dyn Fn(&Arc<dm_tree::frontend::BodySyntaxInput>)->Result<Arc<dm_tree::frontend::BodySyntax>,dm_tree::frontend::BodySyntaxFailure>)->Result<TrackedData,Failure>{collect_using(inputs,root_path,pages,config,tests,root,poll,body,None,false).map(|(data,_)|data)}
pub fn collect_list_macro_fix_from_pages(inputs:&dm_analysis::policy_inputs::PolicyInputs,root_path:&Path,pages:&dyn RawPolicyPages,config:&Config,relative:&str,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,body:&dyn Fn(&Arc<dm_tree::frontend::BodySyntaxInput>)->Result<Arc<dm_tree::frontend::BodySyntax>,dm_tree::frontend::BodySyntaxFailure>)->Result<crate::captured_tracked_fix::ListMacroFixData,Failure>{collect_using(inputs,root_path,pages,config,false,root,poll,body,Some(relative),false)?.1.ok_or_else(||Failure::Unsupported("native fix collection missing actual target".into()))}
/// Full tracked fix planning uses the same admitted declarations/body/raw pages.
pub fn collect_tracked_fix_from_pages(inputs:&dm_analysis::policy_inputs::PolicyInputs,root_path:&Path,pages:&dyn RawPolicyPages,config:&Config,relative:&str,tests:bool,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,body:&dyn Fn(&Arc<dm_tree::frontend::BodySyntaxInput>)->Result<Arc<dm_tree::frontend::BodySyntax>,dm_tree::frontend::BodySyntaxFailure>)->Result<crate::captured_tracked_fix::ListMacroFixData,Failure>{collect_using(inputs,root_path,pages,config,tests,root,poll,body,Some(relative),true)?.1.ok_or_else(||Failure::Unsupported("native fix collection missing actual target".into()))}
fn collect_using(inputs:&dm_analysis::policy_inputs::PolicyInputs,root_path:&Path,pages:&dyn RawPolicyPages,config:&Config,tests:bool,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,body:&dyn Fn(&Arc<dm_tree::frontend::BodySyntaxInput>)->Result<Arc<dm_tree::frontend::BodySyntax>,dm_tree::frontend::BodySyntaxFailure>,fix_target:Option<&str>,tracked_fixes:bool)->Result<(TrackedData,Option<crate::captured_tracked_fix::ListMacroFixData>),Failure>{check(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?,ok:false};let budget=&phase.budget;let pending=(||{let mut work=Operation{budget,poll};let mut fix=fix_target.map(|relative|crate::captured_tracked_fix::ListMacroFixData::new(relative,budget,poll)).transpose()?;let mut tracked=policy::Tracked::new();let mut setup=BTreeSet::new();let mut list_questions=BTreeSet::new();let mut requests=Requests::new();let complete=pages.for_each(&mut|relative,views|{let local=views.allocation_budget(budget);let mut temporary=Operation{budget:local,poll};let pending=(||{check(local,poll)?;let raw=views.raw()?;if raw.contains("derive("){views.code()?;}if raw.contains("setup("){views.clean(local)?;}let file=views.source_file()?;if let Some(fix)=&mut fix{if relative==fix.relative()&&!selected(config,relative,tests){return Err("native fix target is excluded by the actual tracked policy scope".into())}fix.source(file,budget,poll)?;}policy::captures_admission(&mut temporary,None,None)?;policy::tracked_from_text_using(file,&mut tracked,tests,&mut work,&mut temporary)?;policy::setup_hooks_file_using(file,&mut setup,&mut work,&mut temporary)?;if crate::captured_raw_file::is_code_dm(relative){crate::tracked_lists_policy::visit_declarations(raw,relative,&mut temporary,&mut|_,owner,var,_|{if !list_questions.iter().any(|(old_owner,old_var)|old_owner==owner&&old_var==var){kc::reserve(&mut work,||Some(2048))?;list_questions.insert((kc::own(&mut work,owner)?,kc::own(&mut work,var)?));}Ok(())})?;}if selected(config,relative,tests)&&fix_target.is_none_or(|target|relative==target){requests.request(inputs,root_path,relative,budget,local,poll)?;}Ok(true)})();finish(pending,local,poll)})?;if !complete{return Err("tracked declaration source phase stopped before CODE_MAPS_DM EOF".into())}let mut data=TrackedData{tests,sites:Vec::new(),source_text:Vec::new(),allows:Vec::new(),notes:Vec::new(),digests:BTreeMap::new()};if let Some(mut pats)=policy::build_pats_using(&tracked,&mut work)?{pats.setup=setup;let mut lists=policy::Tracked::new();for(owner,var)in list_questions{work.checkpoint()?;if list_schema(inputs,&owner,&var,root,poll)?{if !lists.contains_key(&var){kc::reserve(&mut work,||Some(2048))?;lists.insert(kc::own(&mut work,&var)?,BTreeSet::new());}kc::reserve(&mut work,||Some(2048))?;lists.get_mut(&var).expect("actual tracked list name").insert(owner);}}let lpats=policy::build_list_pats_using(&lists,&mut work)?;let source=ReadSource::native(inputs,root_path,budget)?.with_checkpoint(poll).with_body_borrower(body);requests.prepare(&source,budget,poll)?;let empty=BTreeSet::new();let complete=pages.for_each(&mut|relative,views|{let local=views.allocation_budget(budget);let pending=(||{check(local,poll)?;if !selected(config,relative,tests)||fix_target.is_some_and(|target|target!=relative){return Ok(true)}views.clean(local)?;let file=views.source_file()?;let mut temporary=Operation{budget:local,poll};policy::captures_admission(&mut temporary,Some(&pats),lpats.as_ref())?;let named=requests.get(inputs,root_path,relative,local,poll)?.unwrap_or(&empty);let(hits,_)=if tracked_fixes{policy::scan_one_tracked_fixes_using(&tracked,&pats,&lists,lpats.as_ref(),file,named,&mut temporary,&mut|line|allow(&mut data,file,line,local,budget,poll),&mut|owner,var,action|{
 use crate::reactive_global_source::{Source,SelectedCallable};let mut lookup=Operation{budget:local,poll};lookup.checkpoint()?;kc::reserve(&mut lookup,||var.len().checked_mul(4)?.checked_add(128))?;let Some(method)=action.method(var)else{return Ok(false)};let yes=!matches!(Source::callable(&source,owner,&method)?,SelectedCallable::Missing);lookup.checkpoint()?;Ok(yes)
})?}else{policy::scan_one_for_fix_using(&tracked,&pats,&lists,lpats.as_ref(),file,named,&mut temporary,&mut|line|allow(&mut data,file,line,local,budget,poll),fix.is_some())?};for mut hit in hits{work.checkpoint()?;if let Some(fix)=&mut fix{if tracked_fixes{fix.tracked_hit(file,&mut hit,budget,poll)?}else{fix.hit(file,&mut hit,budget,poll)?}continue;}kc::row(&mut work,&mut data.sites)?;budget.charge(hit.msg.capacity()).map_err(|m|oom(budget,m))?;let line=u32::try_from(hit.line).map_err(|_|oom(budget,"tracked source line overflow"))?;data.sites.push(Site{rule:kc::own(&mut work,policy::metadata(tests).rules[hit.rule as usize].name)?,rel:kc::own(&mut work,relative)?,line,msg:hit.msg,key:String::new(),ident:String::new()});kc::row(&mut work,&mut data.source_text)?;let raw=file.raw();let text=raw.line(hit.line);kc::reserve(&mut work,||text.len().checked_mul(4)?.checked_add(128))?;data.source_text.push(crate::util::normalize_ws(text));}Ok(true)})();finish(pending,local,poll)})?;if !complete{return Err("tracked selected source phase stopped before CODE_MAPS_DM EOF".into())}}kc::row(&mut work,&mut data.notes)?;data.notes.push(kc::format(&mut work,format_args!("tracked vars: {}, writes outside setters: {} (target 0)",tracked.len(),data.sites.len()))?);check(budget,poll)?;if let Some(fix)=&mut fix{fix.set_schema_count(tracked.len());fix.finish(budget,poll)?;}Ok((data,fix))})();let pending=finish(pending,budget,poll);let pending=match pending{Ok((data,fix))=>{let bytes=data.retained_charge().and_then(|n|n.checked_add(fix.as_ref().map_or(Some(0),|fix|fix.retained_charge())?)).ok_or_else(||oom(root,"tracked returned backing overflow"))?;match root.charge(bytes).map_err(|m|oom(root,m)){Ok(())=>Ok((data,fix)),Err(actual)=>{drop((data,fix));Err(actual)}}},Err(actual)=>Err(actual)};phase.ok=pending.is_ok();drop(phase);finish(pending,root,poll)}

/// Raw target-roster DATA only. The host owns the two genuine discovery EOFs.
pub struct FixTargetsData{pub paths:Vec<String>,pub schema_count:usize}
pub fn collect_fix_targets_from_pages(pages:&dyn RawPolicyPages,config:&Config,mode:crate::native_fix_wire::Mode,prefixes:&[String],root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<FixTargetsData,Failure>{
 use crate::native_fix_wire::Mode;check(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?,ok:false};let budget=&phase.budget;let mut work=Operation{budget,poll};let mut tracked=policy::Tracked::new();let mut paths=Vec::new();
 let produced=(||{if !pages.for_each(&mut|_,views|{let local=views.allocation_budget(budget);let mut temporary=Operation{budget:local,poll};let result=(||{let raw=views.raw()?;if raw.contains("derive("){views.code()?;}let file=views.source_file()?;if mode!=Mode::TrackedDropDeclared{policy::captures_admission(&mut temporary,None,None)?;policy::tracked_from_text_using(file,&mut tracked,mode==Mode::TrackedTests,&mut work,&mut temporary)?;}Ok(true)})();finish(result,local,poll)})?{return Err("native FIX schema target phase stopped before actual declaration EOF".into())}
 if !pages.for_each(&mut|relative,_|{work.checkpoint()?;if !prefixes.is_empty()&&!prefixes.iter().any(|prefix|relative.starts_with(prefix)){return Ok(true)}if relative.starts_with("code/_generated/")||relative.starts_with("code/engine/_generated/")||mode==Mode::TrackedDropDeclared&&relative=="code/defines/engine/capabilities.dm"{return Ok(true)}if mode!=Mode::TrackedDropDeclared&&!selected(config,relative,mode==Mode::TrackedTests){return Ok(true)}kc::row(&mut work,&mut paths)?;paths.push(kc::own(&mut work,relative)?);Ok(true)})?{return Err("native FIX selected target phase stopped before actual source EOF".into())}
 paths.sort_unstable();if paths.windows(2).any(|rows|rows[0]==rows[1]){return Err("native FIX actual selected target roster repeats a path".into())}check(budget,poll)?;Ok(FixTargetsData{schema_count:tracked.len(),paths})})();let produced=finish(produced,budget,poll);let produced=match produced{Ok(data)=>{let base=data.paths.capacity().checked_mul(std::mem::size_of::<String>()).and_then(|n|n.checked_add(std::mem::size_of::<FixTargetsData>())).ok_or_else(||oom(root,"native FIX roster retained bound overflow"));let retained=base.and_then(|base|data.paths.iter().try_fold(base,|n,path|n.checked_add(path.capacity()).ok_or_else(||oom(root,"native FIX roster string bound overflow"))));match retained.and_then(|bytes|root.charge(bytes).map_err(|m|oom(root,m))){Ok(())=>Ok(data),Err(actual)=>{drop(data);Err(actual)}}},Err(actual)=>Err(actual)};phase.ok=produced.is_ok();drop(phase);finish(produced,root,poll)
}
